/**
 * In-memory synthetic throughput & RTT benchmark suite (TRD §12, FR-32).
 * Streams pseudo-random generated byte buffers over WebRTC DataChannel (zero disk I/O).
 */

export interface BenchmarkConfig {
  chunkSize: number; // e.g. 16384, 32768, 65536, 131072, 262144
  totalBytes: number; // e.g. 10 * 1024 * 1024 (10 MB)
}

export interface BenchmarkResult {
  chunkSize: number;
  totalBytes: number;
  durationMs: number;
  throughputMbps: number;
  rttMs?: number;
}

/**
 * Creates deterministic pseudo-random chunk payload for testing.
 */
export function generateSyntheticChunk(size: number, seed = 42): Uint8Array {
  const buf = new Uint8Array(size);
  let s = seed;
  for (let i = 0; i < size; i++) {
    s = (s * 1664525 + 1013904223) >>> 0;
    buf[i] = s & 0xff;
  }
  return buf;
}

export function formatMbps(mbps: number): string {
  return `${mbps.toFixed(2)} Mbps`;
}

export function exportResultsToCsv(results: BenchmarkResult[]): string {
  const header = 'Chunk Size (bytes),Total Bytes,Duration (ms),Throughput (Mbps),RTT (ms)\n';
  const rows = results.map(
    (r) => `${r.chunkSize},${r.totalBytes},${r.durationMs.toFixed(1)},${r.throughputMbps.toFixed(2)},${r.rttMs ?? 'N/A'}`
  );
  return header + rows.join('\n');
}
